-- MariaDB 10.4.32 template; LOCAL execution verified under owner approval (see GUIDE).
-- Execute the WHOLE file in ONE session. Change ONLY the target assignment below.
-- Session SET/PREPARE/EXECUTE are used; read-only files never change persistent state.
-- No implicit-schema lookup: DATABASE() is diagnostic ONLY. Do not run selections/tails.
-- Identity/backup/quiescence require independent owner verification; no RELEASE_READY claim.
-- Reset stale state BEFORE operator configuration; do not remove or reorder this reset.
SET @rb_target = NULL, @rb_schema_valid = 0, @rb_schema_exists = 0, @rb_table_ok = 0,
 @rb_engine_ok = 0, @rb_checks_enabled = 0, @rb_ready = 0, @rb_ident = NULL,
 @rb_guard_template = NULL, @rb_ddl = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status', @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
-- ONLY OPERATOR CONFIGURATION: replace placeholder with the independently verified schema.
SET @rb_target = 'edms_smpv_dev';
SET @rb_schema_valid = COALESCE(CHAR_LENGTH(@rb_target) BETWEEN 1 AND 64
 AND LENGTH(@rb_target) = CHAR_LENGTH(@rb_target)
 AND CONVERT(@rb_target USING utf8mb4) COLLATE utf8mb4_bin REGEXP '^[A-Za-z0-9_]+$'
 AND CONVERT(@rb_target USING utf8mb4) COLLATE utf8mb4_bin NOT REGEXP '[^A-Za-z0-9_]'
 AND LOWER(@rb_target) NOT IN ('information_schema','mysql','performance_schema','sys','__set_target_schema__'),0);
SET @rb_engine_ok = (VERSION() LIKE '10.4.32-MariaDB%');
SET @rb_schema_exists = (@rb_schema_valid = 1 AND EXISTS (
 SELECT 1 FROM information_schema.SCHEMATA WHERE BINARY SCHEMA_NAME = BINARY @rb_target));
SET @rb_table_ok = (@rb_schema_exists = 1 AND EXISTS (
 SELECT 1 FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
 AND BINARY TABLE_NAME = BINARY 'workflow_comments' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB'));
SET @rb_ident = IF(@rb_schema_valid = 1 AND @rb_schema_exists = 1,
 CONCAT('`', REPLACE(@rb_target,'`','``'), '`'), NULL);
-- Engine-specific variable is accessed ONLY inside the prepared statement for that engine.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_engine_ok = 1, 'SELECT @@check_constraint_checks INTO @rb_checks_enabled', 'SELECT ''STOP_WRONG_ENGINE'' AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
SET @rb_ready = COALESCE(@rb_schema_valid = 1 AND @rb_schema_exists = 1
 AND @rb_engine_ok = 1 AND @rb_table_ok = 1 AND @rb_checks_enabled = 1 AND @@foreign_key_checks = 1
 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
 AND BINARY TABLE_NAME = BINARY 'workflow_comments' AND COLUMN_NAME IN (
 'id','project_id','document_id','revision_id','workflow_action','workflow_comment','created_by_user_id',
 'created_by_name_snapshot','created_by_username_snapshot','created_by_official_role_snapshot',
 'approval_target_stage_snapshot','request_fingerprint','created_at')) = 13
 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
 AND BINARY TABLE_NAME = BINARY 'workflow_comments') = 13,0);
SET @rb_context_status = CASE
 WHEN @rb_schema_valid <> 1 THEN 'STOP_INVALID_TARGET_SCHEMA'
 WHEN @rb_engine_ok <> 1 THEN 'STOP_WRONG_ENGINE'
 WHEN @rb_schema_exists <> 1 THEN 'STOP_TARGET_SCHEMA_NOT_FOUND'
 WHEN @rb_table_ok <> 1 THEN 'STOP_TARGET_TABLE_MISSING_OR_WRONG_ENGINE'
 WHEN @rb_checks_enabled <> 1 OR @@foreign_key_checks <> 1 THEN 'STOP_CONSTRAINT_CHECKING_DISABLED'
 WHEN @rb_ready <> 1 THEN 'STOP_REQUIRED_COLUMNS_MISSING_OR_UNEXPECTED'
 ELSE 'TARGET_CONFIGURED_VERIFY_IDENTITY_MANUALLY' END;
-- RS01: compare actual server/account identity with trusted environment configuration.
SELECT @rb_target AS target_schema, DATABASE() AS client_selected_schema, VERSION() AS server_version,
 @@version_comment AS version_comment, @@hostname AS hostname, @@port AS port,
 CURRENT_USER() AS authenticated_account, @@session.sql_mode AS sql_mode,
 @@foreign_key_checks AS foreign_key_checks, @rb_context_status AS context_status;
-- RS02: required-column evidence; never changes target even if client switches database.
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,
 CHARACTER_SET_NAME,COLLATION_NAME,ORDINAL_POSITION FROM information_schema.COLUMNS
 WHERE BINARY TABLE_SCHEMA = BINARY @rb_target AND BINARY TABLE_NAME = BINARY 'workflow_comments'
 ORDER BY ORDINAL_POSITION;
-- RS03: fully qualified DDL.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, CONCAT('SHOW CREATE TABLE ',@rb_ident,'.`workflow_comments`'),'SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
-- RS04: exact foreign keys and referential actions; save entire result before/after.
SELECT k.CONSTRAINT_NAME,k.COLUMN_NAME,k.ORDINAL_POSITION,k.REFERENCED_TABLE_SCHEMA,
 k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.UPDATE_RULE,r.DELETE_RULE
 FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r
 ON BINARY r.CONSTRAINT_SCHEMA = BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME = BINARY k.CONSTRAINT_NAME
 WHERE BINARY k.TABLE_SCHEMA = BINARY @rb_target AND BINARY k.TABLE_NAME = BINARY 'workflow_comments'
 ORDER BY k.CONSTRAINT_NAME,k.ORDINAL_POSITION;
-- RS05: full index evidence; required indexes are also checked in the final guard.
SELECT INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,COLLATION,SUB_PART,NULLABLE,INDEX_TYPE
 FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
 AND BINARY TABLE_NAME = BINARY 'workflow_comments' ORDER BY INDEX_NAME,SEQ_IN_INDEX;
-- RS06a: fully qualified counts, with NO hardcoded environment counts.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, CONCAT('SELECT COUNT(*) AS comment_count FROM ',@rb_ident,'.`workflow_comments`'),'SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
-- RS06b: action distribution.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, CONCAT('SELECT workflow_action,HEX(workflow_action) AS action_hex,COUNT(*) AS row_count FROM ',@rb_ident,'.`workflow_comments` GROUP BY workflow_action,HEX(workflow_action) ORDER BY action_hex'),'SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
-- RS06c: lossless per-row content evidence; save/export and compare exactly before/after.
-- Contains comment/actor data: protect exports. Counts alone NEVER prove preservation.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, CONCAT('SELECT id,HEX(CAST(JSON_ARRAY(id,project_id,document_id,revision_id,workflow_action,workflow_comment,created_by_user_id,created_by_name_snapshot,created_by_username_snapshot,created_by_official_role_snapshot,approval_target_stage_snapshot,request_fingerprint,DATE_FORMAT(created_at,''%Y-%m-%d %H:%i:%s.%f'')) AS CHAR CHARACTER SET utf8mb4)) AS row_content_hex FROM ',@rb_ident,'.`workflow_comments` ORDER BY BINARY id'),'SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
-- RS07: raw CHECK text/HEX/enforcement; unknown spelling stays STOP.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, 'SELECT tc.CONSTRAINT_NAME,cc.CHECK_CLAUSE,HEX(cc.CHECK_CLAUSE) AS clause_hex,@@check_constraint_checks AS checks_enabled FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON BINARY cc.CONSTRAINT_SCHEMA = BINARY tc.CONSTRAINT_SCHEMA AND BINARY cc.CONSTRAINT_NAME = BINARY tc.CONSTRAINT_NAME WHERE BINARY tc.CONSTRAINT_SCHEMA = BINARY @rb_target AND BINARY tc.TABLE_NAME = BINARY ''workflow_comments'' AND tc.CONSTRAINT_TYPE = ''CHECK'' ORDER BY tc.CONSTRAINT_NAME','SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;

