  UNION ALL SELECT ''chk_workflow_comments_approval_target_stage'', ''EXPANDED'', ''60617070726F76616C5F7461726765745F73746167655F736E617073686F7460206973206E756C6C206F722060776F726B666C6F775F616374696F6E60203D2027417070726F76616C20412720616E642060617070726F76616C5F7461726765745F73746167655F736E617073686F746020696E2028274946412D5375626D6974746564272C2741532D4275696C742729''
  UNION ALL SELECT ''chk_workflow_comments_emergency_request'', ''BASELINE'', ''''
  UNION ALL SELECT ''chk_workflow_comments_emergency_request'', ''EXPANDED'', ''''
),
actual_checks AS (
 SELECT tc.CONSTRAINT_NAME AS check_name, cc.CHECK_CLAUSE AS clause_text,
   HEX(cc.CHECK_CLAUSE) AS clause_hex, (@@check_constraint_checks = 1) AS enforced
 FROM information_schema.TABLE_CONSTRAINTS tc
 JOIN information_schema.CHECK_CONSTRAINTS cc
   ON BINARY cc.CONSTRAINT_SCHEMA = BINARY tc.CONSTRAINT_SCHEMA
  AND BINARY cc.CONSTRAINT_NAME = BINARY tc.CONSTRAINT_NAME
 WHERE BINARY tc.CONSTRAINT_SCHEMA = BINARY @rb_target
   AND BINARY tc.TABLE_NAME = BINARY ''workflow_comments'' AND tc.CONSTRAINT_TYPE = ''CHECK''
),
check_matches AS (
 SELECT e.phase, COUNT(DISTINCT e.check_name) AS matched
 FROM expected_clauses e JOIN actual_checks a
   ON BINARY a.check_name = BINARY e.check_name AND BINARY a.clause_hex = BINARY e.clause_hex
 WHERE a.enforced = 1 GROUP BY e.phase
),
column_specs (column_name, max_length, nullable) AS (
 SELECT ''workflow_action'',64,''NO'' UNION ALL SELECT ''request_fingerprint'',64,''YES''
 UNION ALL SELECT ''approval_target_stage_snapshot'',64,''YES'' UNION ALL SELECT ''revision_id'',64,''YES''
),
anchor_varchars (column_name, max_length, nullable) AS (
 SELECT ''id'',64,''NO'' UNION ALL SELECT ''project_id'',64,''NO'' UNION ALL SELECT ''document_id'',64,''NO''
 UNION ALL SELECT ''created_by_name_snapshot'',255,''YES'' UNION ALL SELECT ''created_by_username_snapshot'',255,''YES''
 UNION ALL SELECT ''created_by_official_role_snapshot'',64,''YES''
),
fk_specs (constraint_name, column_name, referenced_table, delete_rule) AS (
 SELECT ''fk_workflow_comments_project_id'',''project_id'',''projects'',''RESTRICT''
 UNION ALL SELECT ''fk_workflow_comments_document_id'',''document_id'',''engineering_documents'',''RESTRICT''
 UNION ALL SELECT ''fk_workflow_comments_revision_id'',''revision_id'',''document_revisions'',''SET NULL''
 UNION ALL SELECT ''fk_workflow_comments_created_by_user_id'',''created_by_user_id'',''users'',''SET NULL''
),
index_specs (index_name, seq_no, column_name, non_unique) AS (
 SELECT ''PRIMARY'',1,''id'',0 UNION ALL SELECT ''idx_workflow_comments_project_document'',1,''project_id'',1
 UNION ALL SELECT ''idx_workflow_comments_project_document'',2,''document_id'',1
 UNION ALL SELECT ''idx_workflow_comments_revision_id'',1,''revision_id'',1
 UNION ALL SELECT ''idx_workflow_comments_created_at'',1,''created_at'',1
 UNION ALL SELECT ''idx_workflow_comments_created_by_user_id'',1,''created_by_user_id'',1
),
facts AS (
 SELECT
  (VERSION() LIKE ''10.4.32-MariaDB%'' AND @@check_constraint_checks = 1 AND @rb_target IS NOT NULL AND @@foreign_key_checks = 1) AS engine_ok,
  (SELECT COUNT(*) FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
   AND BINARY TABLE_NAME = BINARY ''workflow_comments'' AND ENGINE = ''InnoDB'') AS table_ok,
  (SELECT COUNT(*) FROM column_specs s JOIN information_schema.COLUMNS c
   ON BINARY c.COLUMN_NAME = BINARY s.column_name
   WHERE BINARY c.TABLE_SCHEMA = BINARY @rb_target AND BINARY c.TABLE_NAME = BINARY ''workflow_comments''
    AND c.DATA_TYPE = ''varchar'' AND c.CHARACTER_MAXIMUM_LENGTH = s.max_length
    AND c.IS_NULLABLE = s.nullable AND (c.COLUMN_DEFAULT IS NULL OR BINARY c.COLUMN_DEFAULT = BINARY ''NULL'') AND c.EXTRA = ''''
    AND c.CHARACTER_SET_NAME = ''utf8mb4'' AND c.COLLATION_NAME = ''utf8mb4_unicode_ci'') AS columns_ok,
  (SELECT COUNT(*) FROM index_specs s JOIN information_schema.STATISTICS i
    ON BINARY i.INDEX_NAME = BINARY s.index_name AND i.SEQ_IN_INDEX = s.seq_no
    AND BINARY i.COLUMN_NAME = BINARY s.column_name AND i.NON_UNIQUE = s.non_unique
    WHERE BINARY i.TABLE_SCHEMA = BINARY @rb_target AND BINARY i.TABLE_NAME = BINARY ''workflow_comments''
     AND i.SUB_PART IS NULL AND i.INDEX_TYPE = ''BTREE'' AND i.COLLATION = ''A''
     AND (SELECT COUNT(*) FROM information_schema.STATISTICS x
       WHERE BINARY x.TABLE_SCHEMA = BINARY @rb_target AND BINARY x.TABLE_NAME = BINARY ''workflow_comments''
         AND BINARY x.INDEX_NAME = BINARY s.index_name) =
       (SELECT COUNT(*) FROM index_specs y WHERE BINARY y.index_name = BINARY s.index_name)) AS index_columns_ok,
  ((SELECT COUNT(*) FROM anchor_varchars s JOIN information_schema.COLUMNS c
     ON BINARY c.COLUMN_NAME = BINARY s.column_name
     WHERE BINARY c.TABLE_SCHEMA = BINARY @rb_target AND BINARY c.TABLE_NAME = BINARY ''workflow_comments''
       AND c.DATA_TYPE = ''varchar'' AND c.CHARACTER_MAXIMUM_LENGTH = s.max_length
       AND c.IS_NULLABLE = s.nullable AND (c.COLUMN_DEFAULT IS NULL OR BINARY c.COLUMN_DEFAULT = BINARY ''NULL'') AND c.EXTRA = ''''
       AND c.CHARACTER_SET_NAME = ''utf8mb4'' AND c.COLLATION_NAME = ''utf8mb4_unicode_ci'')
   + (SELECT COUNT(*) FROM information_schema.COLUMNS c
     WHERE BINARY c.TABLE_SCHEMA = BINARY @rb_target AND BINARY c.TABLE_NAME = BINARY ''workflow_comments'' AND (
       (BINARY c.COLUMN_NAME = BINARY ''workflow_comment'' AND c.DATA_TYPE = ''text'' AND c.IS_NULLABLE = ''YES''
         AND (c.COLUMN_DEFAULT IS NULL OR BINARY c.COLUMN_DEFAULT = BINARY ''NULL'') AND c.EXTRA = '''' AND c.CHARACTER_SET_NAME = ''utf8mb4'' AND c.COLLATION_NAME = ''utf8mb4_unicode_ci'') OR
       (BINARY c.COLUMN_NAME = BINARY ''created_by_user_id'' AND BINARY c.COLUMN_TYPE = BINARY ''bigint(20) unsigned''
         AND c.IS_NULLABLE = ''YES'' AND (c.COLUMN_DEFAULT IS NULL OR BINARY c.COLUMN_DEFAULT = BINARY ''NULL'') AND c.EXTRA = '''') OR
       (BINARY c.COLUMN_NAME = BINARY ''created_at'' AND c.DATA_TYPE = ''datetime'' AND c.DATETIME_PRECISION = 3
         AND c.IS_NULLABLE = ''NO'' AND LOWER(c.COLUMN_DEFAULT) = ''current_timestamp(3)''
         AND c.EXTRA = '''')
     ))) AS anchor_columns_ok,
  (SELECT COUNT(*) FROM actual_checks) AS check_count,
  COALESCE((SELECT matched FROM check_matches WHERE phase = ''BASELINE''),0) AS baseline_matches,
  COALESCE((SELECT matched FROM check_matches WHERE phase = ''EXPANDED''),0) AS expanded_matches,
  (SELECT COUNT(*) FROM fk_specs s JOIN information_schema.KEY_COLUMN_USAGE k
    ON BINARY k.CONSTRAINT_NAME = BINARY s.constraint_name AND BINARY k.COLUMN_NAME = BINARY s.column_name
   JOIN information_schema.REFERENTIAL_CONSTRAINTS r
    ON BINARY r.CONSTRAINT_SCHEMA = BINARY k.CONSTRAINT_SCHEMA AND BINARY r.CONSTRAINT_NAME = BINARY k.CONSTRAINT_NAME
   WHERE BINARY k.TABLE_SCHEMA = BINARY @rb_target AND BINARY k.TABLE_NAME = BINARY ''workflow_comments''
    AND BINARY k.REFERENCED_TABLE_SCHEMA = BINARY @rb_target
    AND BINARY k.REFERENCED_TABLE_NAME = BINARY s.referenced_table AND BINARY k.REFERENCED_COLUMN_NAME = BINARY ''id''
    AND k.ORDINAL_POSITION = 1 AND r.UPDATE_RULE = ''RESTRICT'' AND r.DELETE_RULE = s.delete_rule) AS fk_matches,
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE BINARY TABLE_SCHEMA = BINARY @rb_target
    AND BINARY TABLE_NAME = BINARY ''workflow_comments'' AND REFERENCED_TABLE_NAME IS NOT NULL) AS fk_column_count,
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_NAME IS NOT NULL AND (
    (BINARY TABLE_SCHEMA = BINARY @rb_target AND BINARY TABLE_NAME = BINARY ''workflow_comments''
     AND COLUMN_NAME IN (''workflow_action'',''request_fingerprint'',''approval_target_stage_snapshot'')) OR
    (BINARY REFERENCED_TABLE_SCHEMA = BINARY @rb_target AND BINARY REFERENCED_TABLE_NAME = BINARY ''workflow_comments''
     AND REFERENCED_COLUMN_NAME IN (''workflow_action'',''request_fingerprint'',''approval_target_stage_snapshot'')))) AS incompatible_fk_count,
  (SELECT COUNT(*) FROM __RB_TABLE__ WHERE workflow_action IS NULL
   OR (workflow_action IN (''Approval A'', ''Approval B'', ''Approval C'', ''Emergency Workflow Attachment'', ''Response to Approval B'')) IS FALSE OR (((workflow_action = ''Emergency Workflow Attachment'' AND request_fingerprint IS NOT NULL AND CHAR_LENGTH(request_fingerprint) = 64 AND revision_id IS NULL AND approval_target_stage_snapshot IS NULL) OR (workflow_action IN (''Approval A'', ''Approval B'', ''Approval C'') AND request_fingerprint IS NULL)) OR (workflow_action = ''Response to Approval B'' AND request_fingerprint IS NULL AND approval_target_stage_snapshot IS NULL)) IS FALSE OR (approval_target_stage_snapshot IS NULL OR (workflow_action = ''Approval A'' AND approval_target_stage_snapshot IN (''IFA-Submitted'', ''AS-Built''))) IS FALSE OR (created_by_official_role_snapshot IS NULL OR created_by_official_role_snapshot IN (''Admin'', ''Document Owner'', ''Team Process'', ''Team Project'', ''Viewer'')) IS FALSE) AS incompatible_rows
),
verdict AS (
 SELECT *, (@rb_ready = 1 AND engine_ok = 1 AND table_ok = 1 AND columns_ok = 4 AND anchor_columns_ok = 9 AND index_columns_ok = 6 AND check_count = 4
   AND fk_matches = 4 AND fk_column_count = 4 AND incompatible_fk_count = 0 AND incompatible_rows = 0) AS common_ok
 FROM facts
)';
-- RB_GUARD_TEMPLATE_END
-- RS08: fail-closed summary. No runtime insert tests or persistent mutations.
SET @rb_sql = 'SELECT ''STOP_VALIDATION_NOT_COMPLETED'' AS status';
SET @rb_sql = IF(@rb_ready = 1, REPLACE(CONCAT(@rb_guard_template,'
SELECT *, CASE
 WHEN @rb_ready <> 1 THEN @rb_context_status
 WHEN common_ok <> 1 THEN ''STOP_STRUCTURE_OR_DATA_MISMATCH''
 WHEN expanded_matches = 4 THEN ''ALREADY_APPLIED_DO_NOT_RERUN''
 WHEN baseline_matches = 4 THEN ''BASELINE_MATCH_OWNER_APPROVAL_REQUIRED''
 ELSE ''STOP_UNVERIFIED_CHECK_REPRESENTATION'' END AS status,
 @rb_target AS verified_target_schema,
 ''MANUAL: environment identity, backup, writer quiescence, DDL and row_content_hex comparison'' AS outstanding_evidence
FROM verdict'),'__RB_TABLE__',CONCAT(@rb_ident,'.`workflow_comments`')),'SELECT @rb_context_status AS status');
PREPARE rb_read FROM @rb_sql;
EXECUTE rb_read;
DEALLOCATE PREPARE rb_read;
